CREATE TRIGGER asset_file_projection_notices_insert AFTER INSERT ON notices BEGIN DELETE FROM asset_file_reference_paths WHERE row_table='notices' AND row_key=json_array(NEW.id) AND NOT EXISTS(SELECT 1 FROM asset_file_reference_inputs raw WHERE raw.row_table='notices' AND raw.row_id=NEW.id AND raw.field=asset_file_reference_paths.field AND raw.raw_url=asset_file_reference_paths.raw_url); INSERT INTO asset_file_reference_paths(row_table,row_key,field,raw_url,origin,path) SELECT row_table,row_key,field,raw_url,(SELECT iif(instr(v,'://')>0,substr(v,1,instr(v,'://')+1+instr(substr(v,instr(v,'://')+3)||'/','/')),iif(substr(v,1,2)='//',substr(v,1,1+instr(substr(v,3)||'/','/')),NULL)) FROM (SELECT trim(raw_url) v)),(WITH RECURSIVE u(state,low,high,next) AS (VALUES (0,'00','7F',0),(0,'C2','DF',1),(0,'E0','E0',4),(0,'E1','EC',2),(0,'ED','ED',5),(0,'EE','EF',2),(0,'F0','F0',6),(0,'F1','F3',3),(0,'F4','F4',7),(1,'80','BF',0),(2,'80','BF',1),(3,'80','BF',2),(4,'A0','BF',1),(5,'80','9F',1),(6,'90','BF',2),(7,'80','8F',2)), p(x) AS MATERIALIZED (SELECT replace(replace(replace(replace(trim((SELECT iif(origin IS NULL,iif(substr(replace(replace(replace(replace(value,char(9),''),char(10),''),char(13),''),char(92),'/'),1,2)='//','/',value),substr(value,length(origin)+1)) FROM (SELECT trim(raw_url) value,(SELECT iif(instr(v,'://')>0,substr(v,1,instr(v,'://')+1+instr(substr(v,instr(v,'://')+3)||'/','/')),iif(substr(v,1,2)='//',substr(v,1,1+instr(substr(v,3)||'/','/')),NULL)) FROM (SELECT trim(raw_url) v)) origin))),char(9),''),char(10),''),char(13),''),char(92),'/')), n(r,a) AS (SELECT substr(substr(x,1,min(instr(x||'?','?'),instr(x||'#','#'))-1),2)||'/',json_array() FROM p WHERE substr(x,1,1)='/' UNION ALL SELECT substr(r,instr(r,'/')+1), CASE replace(lower(substr(r,1,instr(r,'/')-1)),'%2e','.') WHEN '.' THEN iif(instr(r,'/')=length(r),json_insert(a,'$[#]',''),a) WHEN '..' THEN iif(instr(r,'/')=length(r),json_insert(json_remove(a,'$[#-1]'),'$[#]',''),json_remove(a,'$[#-1]')) ELSE json_insert(a,'$[#]',substr(r,1,instr(r,'/')-1)) END FROM n WHERE r<>''), j(v) AS (SELECT '/'||COALESCE(group_concat(value,'/'),'') FROM n,json_each(a) WHERE r=''), d(r,v,n) AS (SELECT v,'',0 FROM j UNION ALL SELECT substr(r,iif(r GLOB '%[0-9A-Fa-f][0-9A-Fa-f]*',4,2)),v||iif(r GLOB '%[0-9A-Fa-f][0-9A-Fa-f]*',char((instr('0123456789ABCDEF',upper(substr(r,2,1)))-1)*16+instr('0123456789ABCDEF',upper(substr(r,3,1)))-1),substr(r,1,1)), iif(substr(r,1,1)<>'%',iif(n=0,0,-1),iif(r GLOB '%[0-9A-Fa-f][0-9A-Fa-f]*', coalesce((SELECT next FROM u WHERE state=d.n AND upper(substr(d.r,2,2)) BETWEEN low AND high),-1),-1)) FROM d WHERE r<>'' AND n>=0), e(x) AS MATERIALIZED (SELECT replace(replace(replace(replace(v,char(9),''),char(10),''),char(13),''),char(92),'/') FROM d WHERE r='' AND n=0), s(r,a) AS (SELECT substr(substr(x,1,min(instr(x||'?','?'),instr(x||'#','#'))-1),2)||'/',json_array() FROM e WHERE substr(x,1,1)='/' AND substr(x,1,2)<>'//' UNION ALL SELECT substr(r,instr(r,'/')+1), CASE substr(r,1,instr(r,'/')-1) WHEN '.' THEN iif(instr(r,'/')=length(r),json_insert(a,'$[#]',''),a) WHEN '..' THEN iif(instr(r,'/')=length(r),json_insert(json_remove(a,'$[#-1]'),'$[#]',''),json_remove(a,'$[#-1]')) ELSE json_insert(a,'$[#]',substr(r,1,instr(r,'/')-1)) END FROM s WHERE r<>'') SELECT '/'||COALESCE(group_concat(value,'/'),'') FROM s,json_each(a) WHERE r='') FROM asset_file_reference_inputs WHERE row_table='notices' AND row_id=NEW.id ON CONFLICT(row_table,row_key,field) DO UPDATE SET raw_url=excluded.raw_url,origin=excluded.origin,path=excluded.path WHERE asset_file_reference_paths.raw_url<>excluded.raw_url OR asset_file_reference_paths.origin IS NOT excluded.origin OR asset_file_reference_paths.path<>excluded.path;INSERT INTO asset_file_retention_releases(logical_key,released_at,held) SELECT candidate.logical_key,0,1 FROM (SELECT DISTINCT iif(f.path LIKE '/r2-assets/notices/thumbnails/%',substr(f.path,12),iif(f.path LIKE '/notices/thumbnails/%',substr(f.path,2),NULL)) logical_key FROM asset